MAX_WINDOW_TOKENS = 180000

SYSTEM_RULES = "never force-push, always run the suite before committing"

PINNED = [SYSTEM_RULES]


class CompactionInvariantError(RuntimeError):
    """A pinned rule did not survive compaction. Refuse to continue."""


def must_preserve(window):
    """Compaction invariant, enforced at runtime on every compaction."""
    blob = "\n".join(m["content"] for m in window)
    for rule in PINNED:
        if rule not in blob:
            raise CompactionInvariantError(rule)


def compact(messages, llm):
    summary = llm.summarize(messages[:-5])
    kept = [{"role": "system", "content": r} for r in PINNED]
    window = kept + [{"role": "user", "content": summary}] + messages[-5:]
    must_preserve(window)
    return window


def step(messages, llm):
    if count_tokens(messages) > MAX_WINDOW_TOKENS:
        messages = compact(messages, llm)
    return llm.respond(messages)
